const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const finite = v => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));
const n = v => finite(v) ? Number(v) : 0;
const money = (v, digits=0) => finite(v) ? new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:digits,minimumFractionDigits:digits}).format(Number(v)) : '—';
const signed = v => finite(v) ? `${Number(v)>=0?'+':'−'}${money(Math.abs(Number(v)))}` : '—';
const number = v => new Intl.NumberFormat('en-IN',{maximumFractionDigits:2}).format(n(v));
const tone = v => n(v)<0?'negative':'positive';
const date = v => { if(!v) return 'Not available'; const d=new Date(v); return Number.isNaN(+d)?'Not available':d.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'}); };
const stamp = v => { if(!v)return 'Not refreshed yet'; const d=new Date(v);return Number.isNaN(+d)?'Unknown time':d.toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit',timeZone:'Asia/Kolkata'})+' IST'; };
const relative = v => {const h=(Date.now()-new Date(v))/36e5;if(!Number.isFinite(h))return 'not refreshed';if(h<0)return 'time needs checking';if(h<1)return `${Math.max(0,Math.floor(h*60))} min ago`;if(h<24)return `${Math.floor(h)} hr ago`;return `${Math.floor(h/24)} days ago`;};
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',portfolio:'M4 7h16v14H4z M8 7V3h8v4 M4 12h16 M10 12v3h4v-3',ideas:'M9 18h6 M10 22h4 M8 14a7 7 0 1 1 8 0c-1 1-1 2-1 4H9c0-2 0-3-1-4',activity:'M3 12h4l3-8 4 16 3-8h4',more:'M4 5h16 M4 12h16 M4 19h16',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 12-2l2 3 M4 16l2 3a7 7 0 0 0 12-2',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'m12 3 10 18H2z M12 9v5 M12 17v1',close:'m6 6 12 12 M6 18 18 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',logout:'M9 4H4v16h5 M10 12h11 m-5-5 5 5-5 5',phone:'M7 2h10v20H7z M11 18h2',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6z m-5 10 3 3 7-7',external:'M14 3h7v7 M21 3 11 13 M10 3H3v18h18v-7',leaf:'M4 20C2 4 15 2 21 3c1 16-8 20-17 17z M4 20 15 9',settings:'M4 6h16 M4 18h16 M8 3v6 M16 15v6 M4 12h16 M13 9v6'};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const brand = () => '<span class="brand-mark" aria-hidden="true">c<span>l</span></span><span><b>Capital Ledger</b><small>Your investing space</small></span>';
const state={session:null,data:null,page:'home',query:'',account:'All accounts',ideaFilter:'All ideas',activity:'Trades',activityStatus:'All statuses',loading:false,error:null,reconciliation:null};
const tabs=[['home','Overview'],['portfolio','Portfolio'],['ideas','Ideas'],['activity','Activity'],['more','More']];
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
async function api(path, options={}){
 const response=await fetch(`/api/${path}`,{...options,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json',...(state.session?{'X-CSRF-Token':state.session.csrf}:{}),...options.headers}});
 const data=await response.json().catch(()=>({detail:'The connection was interrupted. Please try again.'}));
 if(!response.ok){if(response.status===401&&path!=='login'){state.session=null;state.data=null;state.reconciliation=null;closeDetail();loginPage();}throw new Error(typeof data.detail==='string'?data.detail:'Please check the values and try again.');}return data;
}
function heading(title, subtitle, eyebrow='Your investing space', action=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 tabindex="-1">${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function refreshButton(){return `<button class="btn refresh-btn" data-action="refresh">${icon('refresh')}<span>Refresh accounts</span></button>`;}
function pill(value, color='gray'){return `<span class="badge ${color}">${esc(value)}</span>`;}
function statusLabel(t){const map={Open:'Recorded open',Closed:'Recorded closed',PENDING_BUY:'Awaiting checks',PENDING_FILL:'Awaiting fill',NEEDS_REVIEW:'Needs review',ADVISORY_SELL:'Sell advisory',ERROR:'Needs attention',SKIPPED:'Not bought'};return map[t]||t||'Unknown';}
function statusPill(t){return pill(statusLabel(t),['NEEDS_REVIEW','ERROR','PENDING_FILL'].includes(t)?'amber':t==='Open'?'':'gray');}
function empty(title, text, action=''){return `<div class="empty">${icon('leaf')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;}
function panelHead(title, text='', action=''){return `<div class="panel-head"><div><h2>${esc(title)}</h2>${text?`<p>${esc(text)}</p>`:''}</div>${action}</div>`;}
function link(page,text){return `<a class="btn text" href="#${page}">${esc(text)} ${icon('arrow')}</a>`;}
function filteredHoldings(){return (state.data?.holdings||[]).filter(h=>(state.account==='All accounts'||h.account_label===state.account)&&n(h.quantity)>0);}
function portfolioTotals(){const rows=filteredHoldings();let invested=0,value=0,missing=0;for(const h of rows){if(!finite(h.average_price)||!finite(h.last_price)){missing++;continue;} invested+=n(h.quantity)*n(h.average_price);value+=n(h.quantity)*n(h.last_price);}return {rows,invested,value,pnl:value-invested,pct:invested?(value-invested)/invested*100:null,missing};}
function snapshots(){const rows=state.data?.sync||[];return rows.filter(r=>state.account==='All accounts'||r.account_label===state.account);}
function snapshotKnown(){const expected=state.account==='All accounts'?(state.data?.accounts||[]):[state.account];const got=snapshots();return got.length>0&&expected.every(a=>got.some(r=>r.account_label===a));}
function snapshotStale(){return !snapshotKnown()||snapshots().some(r=>Date.now()-new Date(r.synced_at)>864e5);}
function syncStrip(){return `<div class="sync-strip ${snapshotStale()?'stale':''}">${icon('clock')}<span>${snapshots().length?snapshots().map(r=>`${esc(r.account_label)} · ${esc(relative(r.synced_at))}`).join(' &nbsp; / &nbsp; '):'Accounts have not been refreshed yet'}. Broker snapshot, not live prices.${snapshotStale()?' Refresh before reviewing current holdings.':''}</span></div>`;}
function attention(){const d=state.data;if(!d)return[];const items=[];
 if(snapshotStale())items.push({id:'stale',title:'Your account snapshot needs a refresh',body:'See current holdings before reviewing sell triggers.',kind:'refresh'});
 const sums=new Map();for(const h of d.holdings)sums.set(`${h.account_label}:${h.tradingsymbol}`,n(h.quantity)+(sums.get(`${h.account_label}:${h.tradingsymbol}`)||0));
 const groups=new Map();for(const g of d.gtts.filter(g=>String(g.status).toLowerCase()==='active')){const key=`${g.account_label}:${g.symbol}`;if(!groups.has(key))groups.set(key,{account:g.account_label,symbol:g.symbol,qty:0,ids:[]});const v=groups.get(key);v.qty+=n(g.quantity);v.ids.push(g.id);}
 for(const [key,g] of groups){if(d.sync.some(s=>s.account_label===g.account)&&g.qty>(sums.get(key)||0))items.push({id:`gtt-${key}`,title:`${g.symbol}: check sell triggers`,body:`${g.account} account · ${number(g.qty)} shares in active triggers, ${number(sums.get(key)||0)} in the saved holdings snapshot.`,kind:'gtt',...g});}
 for(const t of d.trades.filter(t=>['PENDING_FILL','NEEDS_REVIEW','ERROR'].includes(t.status)))items.push({id:`trade-${t.trade_id}`,title:`${t.stock_name}: ${statusLabel(t.status).toLowerCase()}`,body:t.status==='PENDING_FILL'?'Fill confirmation is unresolved. New spending in this category is held.':t.notes||'This record needs review.',kind:'trade',tid:t.trade_id});
 return items;
}
function attentionRows(items, limit=items.length){return items.slice(0,limit).map(a=>`<div class="attention-row"><button class="attention-link" data-attention="${esc(a.id)}"><span class="attention-icon">${icon(a.kind==='stale'?'clock':'alert')}</span><span><b>${esc(a.title)}</b><p>${esc(a.body)}</p></span>${icon('chevron')}</button></div>`).join('');}
function shell(){const count=attention().length;const nav=tabs.map(([id,title])=>`<a href="#${id}" class="nav-link ${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(id)}${title}</a>`).join('');
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home">${brand()}</a><p class="nav-label">WORKSPACE</p><nav aria-label="Main navigation">${nav}</nav><button class="nav-link ${state.page==='review'?'active':''}" data-action="review">${icon('bell')}Needs attention ${count?`<span class="count">${count}</span>`:''}</button><div class="sidebar-bottom"><button class="nav-link" data-action="install">${icon('phone')}Get it on your iPhone</button><div class="user-card"><span class="avatar">${esc(state.session.username[0].toUpperCase())}</span><span><b>${esc(state.session.username)}</b><small>Private workspace</small></span></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">Workspace ${icon('chevron')}<span>${esc(tabs.find(t=>t[0]===state.page)?.[1]||'Needs attention')}</span></div><a class="brand mobile-brand" href="#home">${brand()}</a><div class="top-actions"><form class="search-wrap" id="global-search">${icon('search')}<input name="query" aria-label="Search investment ideas" placeholder="Search an investment idea…" autocomplete="off"></form><button class="icon-btn" data-action="review" aria-label="Needs attention${count?`, ${count} items`:''}">${icon('bell')}</button><span class="avatar" aria-hidden="true">${esc(state.session.username[0].toUpperCase())}</span></div></header><main id="content"></main></div><nav class="bottom-nav" aria-label="Mobile navigation">${tabs.map(([id,title])=>`<a href="#${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span>${id==='more'&&count?'<i class="nav-dot"></i>':''}</a>`).join('')}</nav>`;
 $('#global-search').addEventListener('submit',e=>{e.preventDefault();state.query=new FormData(e.target).get('query').trim();location.hash='ideas';render();});
 renderContent();
}
function render(){if(!state.session)return; shell();}
function renderContent(){const root=$('#content');if(!root)return;
 if(state.loading&&!state.data){root.innerHTML=heading('Your investing space','Bringing everything into focus…')+'<div class="grid-top"><div class="skeleton"></div><div class="skeleton"></div></div>';return;}
 if(state.error){root.innerHTML=`${heading('Let’s reconnect','Your account information is temporarily unavailable.')}<div class="load-error"><h2>We couldn’t load your portfolio</h2><p>${esc(state.error)}</p><button class="btn primary" data-action="reload">Try again</button><button class="btn text" data-action="logout">Sign out</button></div>`;return;}
 if(!state.data)return;
 const pages={reconcile:reconcilePage,home:homePage,portfolio:portfolioPage,ideas:ideasPage,activity:activityPage,more:morePage,review:reviewPage};root.innerHTML=(pages[state.page]||homePage)();bindPage();
}
function homePage(){const t=portfolioTotals(), b=state.data.budget, items=attention(),known=snapshotKnown();
 return heading('Your capital, at a glance.','A little less noise. A little more perspective.','Portfolio overview',refreshButton())+`<div class="grid-top"><section class="portfolio-hero" aria-label="Broker holdings value"><span class="hero-tag">All accounts · snapshot</span><div><div class="eyebrow">Holdings value${t.missing?' · incomplete prices':''}</div><div class="hero-value money">${known?money(t.value):'—'}</div><div class="hero-pnl ${tone(t.pnl)}">${known?`${signed(t.pnl)} ${finite(t.pct)?`(${t.pct>=0?'+':''}${t.pct.toFixed(2)}%)`:''} <span class="hero-note">unrealised return</span>`:'Refresh accounts to see your portfolio'}</div></div><div class="hero-bottom"><div><small>Cost of holdings</small><strong>${known?money(t.invested):'—'}</strong></div><div><small>Holding entries</small><strong>${known?t.rows.length:'—'}</strong></div><div><small>Accounts</small><strong>${state.data.accounts?.length||state.data.sync.length}</strong></div></div></section><section class="panel budget-panel">${panelHead('Capital plan','Your bot’s budget ledger',`<a href="#more" aria-label="View capital plan">${icon('external')}</a>`)}${budgetRing(b)}<p class="subtle-note">Budget records are separate from your broker holdings.</p></section></div>${syncStrip()}<div class="grid-main"><div class="section-stack"><section class="panel">${panelHead('Your holdings','Largest positions by saved market value',link('portfolio','View all'))}${holdingsTable(t.rows.slice().sort((a,b)=>n(b.quantity)*n(b.last_price)-n(a.quantity)*n(a.last_price)).slice(0,5),true)}</section><section class="panel">${panelHead('Ideas worth a closer look','Recent recommendations · research inputs, not buy instructions',link('ideas','Explore'))}${recentIdeas()}</section></div><div class="section-stack"><section class="panel home-attention">${panelHead('Needs attention',`${items.length} item${items.length===1?'':'s'} to review`,pill(items.length,'amber'))}${items.length?attentionRows(items,3):'<div class="attention-intro">'+icon('check')+'No issues flagged by the saved snapshot.</div>'}${items.length?link('review','Open review inbox'):''}</section><section class="panel home-allocation">${panelHead('Where your budget sits','Recorded deployment by category')}${allocations()}</section></div></div>`;
}
function budgetRing(b){const pct=Math.max(0,Math.min(100,n(b.utilization_pct)));return `<div class="budget-body"><div class="ring" style="--percent:${pct}" role="img" aria-label="${esc(number(b.utilization_pct))} percent of budget recorded as deployed"><div class="ring-label"><b>${number(b.utilization_pct)}<small>%</small></b><small>deployed</small></div></div><div class="budget-legend"><div class="legend-item"><span class="dot"></span>Recorded investment<b>${money(b.invested)}</b></div><div class="legend-item"><span class="dot pale"></span>Unallocated balance<b>${money(b.available)}</b></div></div></div>`;}
function allocations(){return state.data.categories.map((c,i)=>`<div class="allocation-row"><div class="allocation-label"><b>${esc(c.category_name)}</b><span>${money(c.invested)} / ${money(c.category_budget)}</span></div><div class="bar"><span style="width:${Math.max(0,Math.min(100,n(c.category_budget)?100*n(c.invested)/n(c.category_budget):0))}%;opacity:${1-i*.09}"></span></div></div>`).join('')||'<p class="subtle-note">No category allocations yet.</p>';}
function holdingsTable(rows,compact=false){if(!rows.length)return empty('No holdings to show',snapshotKnown()?'There are no holdings in this account snapshot.':'Refresh accounts to load your broker holdings.');return `<div class="table-scroll"><table><thead><tr><th>Company</th>${compact?'':'<th class="mobile-hide">Quantity</th><th class="mobile-hide">Average cost</th>'}<th>Value</th><th>Return</th></tr></thead><tbody>${rows.map(h=>{const value=finite(h.last_price)?n(h.quantity)*n(h.last_price):null,cost=finite(h.average_price)?n(h.quantity)*n(h.average_price):null,pnl=value!==null&&cost!==null?value-cost:null;return `<tr><td><button class="stock-open" data-holding="${esc(h.tradingsymbol)}" data-account="${esc(h.account_label)}"><span class="stock-logo">${esc(h.tradingsymbol?.slice(0,2))}</span><span><span class="stock-title">${esc(h.tradingsymbol)}</span><span class="cell-sub">${esc(h.account_label)} · ${number(h.quantity)} shares</span></span></button></td>${compact?'':`<td class="mobile-hide">${number(h.quantity)}</td><td class="mobile-hide">${money(h.average_price,2)}</td>`}<td><span class="cell-main money">${money(value)}</span><span class="cell-sub">${money(h.last_price,2)} / share</span></td><td><span class="cell-main ${tone(pnl)} money">${signed(pnl)}</span><span class="cell-sub">${cost&&pnl!==null?(pnl/cost*100).toFixed(2)+'%':'—'}</span></td></tr>`;}).join('')}</tbody></table></div>`;}
function recentIdeas(){return state.data.ideas.slice(0,3).map(t=>`<div class="attention-row"><button class="attention-link" data-trade="${t.trade_id}"><span class="stock-logo">${esc(t.stock_name?.slice(0,2).toUpperCase())}</span><span><b>${esc(t.stock_name)}</b><p>${date(t.buy_date)} · ${esc(statusLabel(t.status))}</p></span><span style="margin-left:auto">${pill(finite(t.conviction)?`${number(t.conviction)} / 100`:'Unscored')}</span></button></div>`).join('')||empty('Your ideas will appear here','Recommendations are added when the advisory pipeline runs.');}
function portfolioPage(){const t=portfolioTotals();const rows=t.rows.filter(h=>String(h.tradingsymbol).toLowerCase().includes(state.query.toLowerCase()));return heading('A closer look at what you own.','Broker holdings are shown separately from recorded trades.','Your portfolio',refreshButton())+`<div class="mini-stats"><div class="stat"><small>Holdings value</small><b>${snapshotKnown()?money(t.value):'—'}</b><p>Saved broker snapshot</p></div><div class="stat"><small>Unrealised return</small><b class="${tone(t.pnl)}">${snapshotKnown()?signed(t.pnl):'—'}</b><p>Against average cost</p></div><div class="stat"><small>Holding entries</small><b>${snapshotKnown()?t.rows.length:'—'}</b><p>Across selected accounts</p></div></div><div class="toolbar"><input class="field-search" id="portfolio-search" type="search" aria-label="Search holdings" placeholder="Find a company or symbol…" value="${esc(state.query)}"><select class="select" id="account-filter" aria-label="Filter account">${['All accounts',...(state.data.accounts||state.data.sync.map(x=>x.account_label))].map(x=>`<option ${state.account===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="btn" data-action="export-holdings">${icon('download')}Export</button></div>${syncStrip()}<section class="panel" id="holding-results">${holdingsTable(rows)}</section><p class="disclosure">${t.missing?`${t.missing} holding(s) have missing prices and are excluded from totals. `:''}These are saved account holdings, not the bot’s “Open” trade records. Intraday or unsettled quantities may need separate reconciliation in Kite.</p>`;}
function ideasPage(){let ideas=state.data.ideas.filter(t=>`${t.stock_name} ${t.notes||''}`.toLowerCase().includes(state.query.toLowerCase()));if(state.ideaFilter==='With interest')ideas=ideas.filter(t=>t.have_interest==='Have Interest');if(state.ideaFilter==='Scored 69+')ideas=ideas.filter(t=>t.conviction_model===state.data.policy.model&&finite(t.conviction)&&n(t.conviction)>=state.data.policy.minimum);if(state.ideaFilter==='Not bought')ideas=ideas.filter(t=>t.status==='SKIPPED');return heading('Ideas, with a little more context.','A research universe to explore—not a list of stocks to buy.','Research & recommendations')+`<div class="toolbar"><input class="field-search" id="ideas-search" type="search" aria-label="Search ideas" placeholder="Search company or recommendation notes…" value="${esc(state.query)}"><select class="select" id="ideas-filter" aria-label="Filter ideas">${['All ideas','With interest','Scored 69+','Not bought'].map(x=>`<option ${state.ideaFilter===x?'selected':''}>${x}</option>`).join('')}</select></div><p class="sync-strip">${ideas.length} recommendations · newest first · model scores are not validated forecasts of returns</p><div class="cards-grid">${ideas.slice(0,90).map(t=>`<button class="idea-card" data-trade="${t.trade_id}"><div class="idea-head"><span class="stock-logo">${esc(t.stock_name?.slice(0,2).toUpperCase())}</span>${statusPill(t.status)}</div><div><h3>${esc(t.stock_name)}</h3><div class="idea-meta">${date(t.buy_date)} · #${t.trade_id}</div></div><div class="idea-prices"><div><small>Recommended price</small><b>${money(t.recommended_price,2)}</b></div><div><small>Advisory target</small><b>${money(t.target_price,2)}</b></div></div><div class="idea-foot"><span class="score">${finite(t.conviction)?`<strong>${number(t.conviction)}</strong><small>/ 100 · ${esc(t.conviction_model||'unknown model')}</small>`:'Not scored yet'}</span>${icon('arrow')}</div></button>`).join('')}</div>${!ideas.length?empty('No matching ideas','Try a different company or clear the filter.'):ideas.length>90?'<p class="disclosure">Showing the latest 90 matches. Search to narrow the list; all records remain available in Activity.</p>':''}`;}
function activityPage(){const d=state.data;let rows=state.activity==='Trades'?d.trades:state.activity==='Orders'?d.orders:d.gtts;const statuses=[...new Set(rows.map(r=>r.status))].filter(Boolean).sort();if(state.activityStatus!=='All statuses')rows=rows.filter(r=>r.status===state.activityStatus);rows=rows.filter(r=>`${r.stock_name||''} ${r.symbol||r.tradingsymbol||''} ${r.trade_id||r.order_id||r.id}`.toLowerCase().includes(state.query.toLowerCase()));return heading('Every action, in one place.','Track recommendations, recorded trades and broker instructions.','Activity')+`<div class="toolbar"><div class="tabs" aria-label="Activity type">${['Trades','Orders','Sell triggers'].map(v=>`<button data-activity="${v}" class="${state.activity===v?'active':''}" aria-pressed="${state.activity===v}">${v}</button>`).join('')}</div><select class="select" id="activity-filter" aria-label="Filter activity status">${['All statuses',...statuses].map(v=>`<option value="${esc(v)}" ${v===state.activityStatus?'selected':''}>${esc(v==='All statuses'?v:state.activity==='Trades'?statusLabel(v):v)}</option>`).join('')}</select><button class="btn" data-action="export-trades">${icon('download')}Export ledger</button><input class="field-search" id="activity-search" type="search" aria-label="Search activity" placeholder="Find company, symbol or reference…" value="${esc(state.query)}"></div>${state.activity!=='Trades'?syncStrip():`<p class="sync-strip">${rows.length} recorded entries · “Recorded open” does not confirm you currently hold the shares.</p>`}<section class="panel">${rows.length?`<div class="table-scroll"><table><thead><tr><th>Company / reference</th><th class="mobile-hide">${state.activity==='Trades'?'Category':'Quantity'}</th><th>${state.activity==='Sell triggers'?'Trigger price':'Price'}</th><th>Status</th></tr></thead><tbody>${rows.map(r=>{const trade=state.activity==='Trades';return `<tr><td>${trade?`<button class="stock-open" data-trade="${r.trade_id}">`:'<span class="stock-cell">'}<span><span class="stock-title">${esc(r.stock_name||r.symbol||r.tradingsymbol)}</span><span class="cell-sub">${trade?`#${r.trade_id} · ${date(r.buy_date)}`:`${esc(r.account_label)} · ${esc(r.order_id||r.id)}`}</span></span>${trade?'</button>':'</span>'}</td><td class="mobile-hide">${trade?esc(r.category_name):number(r.quantity)}</td><td>${money(trade?r.my_buy_price:state.activity==='Orders'?r.average_price||r.price:r.trigger_price,2)}</td><td>${trade?statusPill(r.status):pill(r.status,String(r.status).toLowerCase()==='active'?'':'gray')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Nothing here yet','No entries match this view and filter.')}</section>`;}
function reviewPage(){const items=attention();return heading('A small inbox for important things.','Review discrepancies before making changes to your records.','Needs attention',refreshButton())+syncStrip()+`<div class="toolbar"><button class="btn primary" data-action="symbols">${icon('check')}Confirm stock symbols</button><button class="btn" data-action="reconcile">${icon('shield')}Reconcile holdings & GTTs</button></div><section class="panel">${panelHead('Your review inbox',`${items.length} snapshot and record checks`)}<p class="attention-intro">${icon('shield')}These are review flags, not instructions to sell or cancel every listed trigger. No trade is placed from this screen.</p>${items.length?attentionRows(items):empty('Nothing flagged right now','This checks saved snapshots and unresolved records. It does not guarantee every position is reconciled.')}</section>`;}
function morePage(){const d=state.data,b=d.budget,p=d.performance;return heading('Make this space yours.','Your capital plan, account updates and app preferences.','Workspace')+`<div class="grid-main"><div class="section-stack"><section class="panel">${panelHead('Your capital plan','Budget tracked by the investing bot',`<button class="btn text" data-action="budget">Edit ${icon('settings')}</button>`)}<div class="stat" style="padding:0;border:0"><small>Total budget</small><b>${money(b.total_budget)}</b></div>${budgetRing(b)}<p class="subtle-note">An unallocated ledger balance is not necessarily spendable cash. Pending fills and unresolved records can hold new spending.</p><div style="margin-top:24px">${allocations()}</div></section><section class="panel">${panelHead('Recorded performance','Realised results from closed ledger entries')}<div class="detail-pairs"><div><small>Recorded realised P&L</small><strong class="${tone(p.total_realized)}">${signed(p.total_realized)}</strong></div><div><small>Recorded closed trades</small><strong>${number(p.trade_count)}</strong></div></div>${trend(d.history)}<p class="disclosure">Based on recorded exits. Reconciliation and missing execution data can affect these figures.</p></section><section class="panel">${panelHead('Trading rules','The deployed sizing policy')}<div class="policy-row"><span>Advisory interest</span><b>Have Interest required</b></div><div class="policy-row"><span>Score model for sizing</span><b>${esc(d.policy.model)}</b></div>${d.policy.bands.map(([floor,amount],i)=>`<div class="policy-row"><span>${i===0?`Score above ${floor}`:`Score ${d.policy.minimum}–${d.policy.bands[0][0]}`}</span><b>${money(amount)}</b></div>`).join('')}<p class="disclosure">No buy below ${d.policy.minimum}. Budgets and execution checks still apply. A high score is not proof of future returns.</p></section></div><div class="section-stack"><section class="panel">${panelHead('Connected accounts','Refresh only when you choose',refreshButton())}${(d.accounts||d.sync.map(s=>s.account_label)).map(a=>{const row=d.sync.find(s=>s.account_label===a);return `<div class="account-row"><div><b>${esc(a==='NEW'?'Investing account':'Personal account')}</b><small>${esc(a)} · ${row?`${number(row.holdings_count)} holding entries`:'Not refreshed yet'}</small><small>${row?stamp(row.synced_at):'Refresh to load account data'}</small></div>${pill(row?'Connected':'Not synced',row?'':'amber')}</div>`;}).join('')}</section><section class="panel">${panelHead('On your iPhone','A private app, one tap away')}<button class="setting-link" data-action="install"><span><b>Add to Home Screen</b><small>Open full screen, with your own app icon</small></span>${icon('phone')}</button><div class="setting-link"><span><b>Remembered sign-in</b><small>This session expires ${date(new Date(state.session.expires*1000))}</small></span>${icon('shield')}</div><button class="setting-link" data-action="logout"><span>Sign out of this device</span>${icon('logout')}</button></section><section class="panel">${panelHead('More tools','Your existing advanced workflows')}<button class="setting-link" data-action="symbols"><span><b>Confirm stock symbols</b><small>Check the company, then confirm its NSE ticker</small></span>${icon('check')}</button><button class="setting-link" data-action="classify"><span><b>Company & classification lookup</b><small>Search ticker, company and market-cap classification</small></span>${icon('search')}</button><button class="setting-link" data-action="reconcile"><span><b>Reconcile holdings & sell triggers</b><small>Fresh account check, without changing broker orders</small></span>${icon('shield')}</button><a class="setting-link" href="/classic/?page=Category%20Drill-Down"><span><b>Category breakdown</b><small>Category → company size → individual trades</small></span>${icon('external')}</a><a class="setting-link" href="/classic/?page=Settings%20%26%20Edits"><span><b>Allocation settings & record corrections</b><small>Edit category caps or record an actual historical sale</small></span>${icon('external')}</a><a class="setting-link" href="/classic/?page=Set%20Targets"><span><b>Bulk target editor</b><small>Edit targets across several trades</small></span>${icon('external')}</a><a class="setting-link" href="/classic/?page=Conviction"><span><b>Compare all conviction scores</b><small>Evidence, warnings and model breakdowns</small></span>${icon('external')}</a><button class="setting-link" data-action="review"><span><b>Review inbox</b><small>${attention().length} items flagged</small></span>${icon('chevron')}</button><a class="setting-link" href="https://kite.zerodha.com" target="_blank" rel="noopener noreferrer"><span><b>Open Kite</b><small>Manage broker orders and sell triggers</small></span>${icon('external')}</a></section></div></div>`;}
function trend(rows){if(!rows?.length)return '<p class="disclosure">A chart will appear when dated closed-trade records are available.</p>';const valid=rows.filter(r=>finite(r.cumulative_pnl));if(!valid.length)return '';if(valid.length===1)return `<p class="disclosure">${esc(valid[0].month)}: ${signed(valid[0].cumulative_pnl)} recorded cumulative result.</p>`;const vals=valid.map(r=>n(r.cumulative_pnl)),lo=Math.min(0,...vals),hi=Math.max(0,...vals),range=hi-lo||1;const points=vals.map((v,i)=>`${10+i/(vals.length-1)*580},${170-(v-lo)/range*150}`);return `<svg class="trend" viewBox="0 0 600 190" preserveAspectRatio="none" role="img" aria-label="Recorded cumulative realised profit and loss from ${esc(valid[0].month)} to ${esc(valid.at(-1).month)}"><path class="area" d="M${points.join(' L')} L590,185 L10,185 Z"/><path d="M${points.join(' L')}"/></svg><div class="chart-labels"><span>${esc(valid[0].month)}</span><span>${signed(vals.at(-1))} cumulative</span><span>${esc(valid.at(-1).month)}</span></div>`;}
function bindPage(){const bindSearch=(id,update)=>{const el=$(id);if(el)el.addEventListener('input',()=>{const pos=el.selectionStart;state.query=el.value;update?update():renderContent();const next=$(id);next.focus();next.setSelectionRange(pos,pos);});};
 bindSearch('#portfolio-search');bindSearch('#ideas-search');bindSearch('#activity-search');
 $('#account-filter')?.addEventListener('change',e=>{state.account=e.target.value;renderContent();});$('#ideas-filter')?.addEventListener('change',e=>{state.ideaFilter=e.target.value;renderContent();});$('#activity-filter')?.addEventListener('change',e=>{state.activityStatus=e.target.value;renderContent();});
}
let lastFocus;
function openDetail(title,body){const dialog=$('#detail');lastFocus=document.activeElement;dialog.innerHTML=`<header class="detail-head"><h2 id="detail-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close details">${icon('close')}</button></header><div class="detail-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function closeDetail(){const d=$('#detail');if(d.open)d.close();d.innerHTML='';lastFocus?.focus?.();}
function holdingDetail(symbol,account){const h=state.data.holdings.find(h=>h.tradingsymbol===symbol&&h.account_label===account);if(!h)return;const value=finite(h.last_price)?n(h.quantity)*n(h.last_price):null,pnl=value===null?null:value-n(h.quantity)*n(h.average_price);const lots=state.data.trades.filter(t=>t.symbol===symbol&&t.status==='Open');const score=state.data.scores[symbol];openDetail(symbol,`<p>${esc(account)} account · saved broker holding</p><div class="mini-stats" style="margin-top:20px"><div class="stat"><small>Market value</small><b>${money(value)}</b></div><div class="stat"><small>Unrealised return</small><b class="${tone(pnl)}">${signed(pnl)}</b></div></div><section class="panel"><div class="detail-pairs"><div><small>Shares held</small><strong>${number(h.quantity)}</strong></div><div><small>Average cost</small><strong>${money(h.average_price,2)}</strong></div><div><small>Snapshot price</small><strong>${money(h.last_price,2)}</strong></div><div><small>Latest model score</small><strong>${score&&finite(score[0])?`${number(score[0])} / 100 · ${esc(score[1])}`:'Not scored'}</strong></div></div></section><h3>Related open ledger records</h3><p>These records are matched by symbol. They are not proof of holdings in this account.</p>${lots.map(t=>`<div class="lot"><div class="lot-head"><b>${esc(t.category_name)} · #${t.trade_id}</b>${statusPill(t.status)}</div><p>${number(t.my_buy_qty)} shares · target ${money(t.target_price,2)}</p><button class="btn text" data-trade="${t.trade_id}">View record ${icon('arrow')}</button></div>`).join('')||'<p class="disclosure">No matching open trade records.</p>'}<p class="disclosure">Last refreshed: ${stamp(state.data.sync.find(s=>s.account_label===account)?.synced_at)}</p>`);}
function tradeDetail(tid){const t=state.data.trades.find(t=>t.trade_id===Number(tid)),idea=state.data.ideas.find(t=>t.trade_id===Number(tid));if(!t&&!idea)return;const r={...idea,...t};openDetail(r.stock_name,`<div class="idea-head">${statusPill(r.status)}<small>Record #${r.trade_id} · ${date(r.buy_date)}</small></div><section class="panel" style="margin-top:23px"><div class="detail-pairs"><div><small>Category</small><strong>${esc(r.category_name||'Not recorded')}</strong></div><div><small>Symbol</small><strong>${esc(r.symbol||'Needs resolution')}</strong></div><div><small>Recorded quantity</small><strong>${finite(r.my_buy_qty)?number(r.my_buy_qty):'—'}</strong></div><div><small>Recorded purchase price</small><strong>${money(r.my_buy_price,2)}</strong></div><div><small>Target price</small><strong>${money(r.target_price,2)}</strong></div><div><small>SPTulsian interest</small><strong>${esc(r.have_interest||'Unknown')}</strong></div><div><small>Model score</small><strong>${finite(r.conviction)?`${number(r.conviction)} / 100`:'Not scored'}</strong></div><div><small>Score model</small><strong>${esc(r.conviction_model||'Not recorded')}</strong></div></div></section>${r.notes?`<h3>What happened</h3><p>${esc(r.notes)}</p>`:''}${r.gtt_id?`<p class="disclosure">Recorded sell trigger: ${esc(r.gtt_id)}. Check broker status in Activity.</p>`:''}${r.status==='NEEDS_REVIEW'?`<p class="notebox">Confirm the exact company and exchange symbol. This only returns the recommendation to the normal checked queue.</p><button class="btn primary" data-resolve-symbol="${r.trade_id}">Check & confirm symbol ${icon('arrow')}</button>`:''}${r.status==='Open'?`<p class="notebox">“Recorded open” is a ledger status. Check current broker holdings before editing an old position.</p><button class="btn primary" data-edit-target="${r.trade_id}">Edit target ${icon('arrow')}</button>`:''}<button class="btn text" data-evidence="${r.trade_id}">View score evidence & history ${icon('arrow')}</button><p class="disclosure">Model scores are research inputs, not validated predictions. A target is not a guaranteed sale price.</p>`);}
function targetEditor(tid){const t=state.data.trades.find(t=>t.trade_id===Number(tid));if(!t)return;openDetail(`Target · ${t.stock_name}`,`<p>Record #${t.trade_id} · ${esc(t.symbol)}</p><form id="target-form" style="margin-top:24px"><label class="form-field">Target price (₹)<input name="target_price" type="number" min="0.01" step="0.01" required value="${finite(t.target_price)?n(t.target_price):''}" inputmode="decimal"></label><label class="form-field">Advisory interest<select name="have_interest">${['','Have Interest','No Interest'].map(v=>`<option value="${esc(v)}" ${v===(t.have_interest||'')?'selected':''}>${v||'Unknown'}</option>`).join('')}</select></label><label class="form-field">Timeframe<input name="timeframe" maxlength="50" value="${esc(t.timeframe)}" placeholder="For example, 6–12 months"></label><p class="notebox">This updates the bot’s target record. It does not replace an existing broker GTT. Holdings and trading safeguards still apply.</p><div class="form-error" role="alert"></div><div class="detail-actions"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">Save target</button></div></form>`);
 $('#target-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=$('button[type=submit]',f);b.disabled=true;const values=Object.fromEntries(new FormData(f));try{await api(`trades/${t.trade_id}/target`,{method:'PUT',body:JSON.stringify({...values,target_price:Number(values.target_price),expected_target:t.target_price,expected_interest:t.have_interest,expected_timeframe:t.timeframe})});closeDetail();toast('Target record updated. Existing broker triggers are unchanged.');await load();}catch(err){$('.form-error',f).textContent=err.message;b.disabled=false;}});
}
function budgetEditor(){const b=state.data.budget;openDetail('Your capital plan',`<p>Current budget: <b>${money(b.total_budget)}</b></p><form id="budget-form" style="margin-top:24px"><label class="form-field">New total budget (₹)<input name="amount" type="number" min="1" max="1000000000000" step="1" required value="${n(b.total_budget)}" inputmode="decimal"></label><p class="notebox">Saving changes the budget used by the live bot. It does not move money. Existing category percentages stay the same.</p><div class="form-error" role="alert"></div><div class="detail-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">Save budget</button></div></form>`);$('#budget-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,btt=$('button[type=submit]',f);btt.disabled=true;try{await api('budget',{method:'PUT',body:JSON.stringify({amount:Number(new FormData(f).get('amount')),expected_amount:b.total_budget})});closeDetail();toast('Capital plan updated.');await load();}catch(err){$('.form-error',f).textContent=err.message;btt.disabled=false;}});}
function attentionDetail(id){const a=attention().find(a=>a.id===id);if(!a)return;if(a.kind==='refresh'){refreshAccounts();return;}if(a.kind==='trade'){tradeDetail(a.tid);return;}openDetail(a.title,`<p>${esc(a.body)}</p><p class="notebox">This comparison uses saved snapshots. Refresh your accounts first; settlement, exchange aliases and other orders can affect the result.</p><section class="panel"><h3>Triggers to check in Kite</h3>${a.ids.map(id=>`<div class="account-row"><span>GTT ${esc(id)}</span>${pill(a.account)}</div>`).join('')}</section><p>Review these in your broker account. This app will not cancel triggers or record a sale on your behalf.</p><div class="detail-actions"><a class="btn primary" href="https://kite.zerodha.com" target="_blank" rel="noopener noreferrer">Open Kite ${icon('external')}</a><button class="btn" data-action="close">Done</button></div>`);}
function installDetail(){openDetail('A home on your iPhone',`<div style="display:flex;justify-content:center;margin:10px 0 27px"><img src="/assets/icon-192.png" width="76" height="76" alt="Capital Ledger app icon" style="border-radius:19px"></div><h3>Your investing space. One tap away.</h3><div class="help-steps"><div class="help-step"><span class="step-number">1</span><span>Open this address in <b>Safari</b> on your iPhone.</span></div><div class="help-step"><span class="step-number">2</span><span>Tap <b>Share</b>, then <b>Add to Home Screen</b>. If offered, keep <b>Open as Web App</b> turned on.</span></div><div class="help-step"><span class="step-number">3</span><span>Open the new Capital icon. Sign in once with <b>Remember this device</b> selected.</span></div></div><p class="notebox">Your phone stays signed in for up to 30 days. Safari and the Home Screen app may use separate sessions, so the app can ask you to sign in once after installation.</p><p>Portfolio information needs an internet connection. You can sign out of this device from More at any time.</p>`);}
function exportRows(rows,cols,name){const quote=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv=[cols.map(quote).join(','),...rows.map(r=>cols.map(c=>quote(r[c])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function load(){state.loading=true;state.error=null;render();try{state.data=await api('dashboard');}catch(e){state.error=e.message;}finally{state.loading=false;render();}}
async function refreshAccounts(){document.querySelectorAll('[data-action="refresh"]').forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');});toast('Refreshing your broker snapshots…');try{const r=await api('refresh',{method:'POST',body:'{}'});const entries=Object.entries(r.accounts);toast(entries.map(([a,v])=>v.error?`${a}: refresh failed; previous snapshot kept`:`${a}: refreshed`).join(' · ')||'No accounts are configured.');await load();}catch(e){toast(e.message);render();}}
function loginPage(message=''){$('#app').innerHTML=`<div class="login-page"><section class="login-story"><a class="brand" href="/">${brand()}</a><div><div class="eyebrow" style="color:#aec4ab;margin-bottom:23px">Designed for the long view</div><h1>Your capital.<br>Your conviction.<br><em>A clearer view.</em></h1><p>Bring your holdings, investment ideas and next steps into one calm space.</p><div class="login-art" aria-hidden="true"><span></span><span></span><span></span><span></span></div></div><footer>PRIVATE BY DESIGN &nbsp; · &nbsp; MADE FOR EVERYDAY CLARITY</footer></section><section class="login-form-wrap"><form class="login-form" id="login-form"><a class="brand mobile-brand" href="/">${brand()}</a><div class="eyebrow">Welcome to your workspace</div><h2>Good to have you back.</h2><p>Sign in to see the bigger picture.</p><label class="form-field">Username<input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" required maxlength="100" placeholder="Your username"></label><label class="form-field">Password<input name="password" type="password" autocomplete="current-password" required maxlength="500" placeholder="Your password"></label><label class="checkbox"><input name="remember" type="checkbox" checked>Remember this device for 30 days</label><div class="form-error" role="alert">${esc(message)}</div><button class="btn primary" type="submit">Enter your workspace ${icon('arrow')}</button><p class="login-caption">Your existing dashboard sign-in works here.<br>Use a personal device to stay signed in.</p></form></section></div>`;
 $('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=$('button[type=submit]',f);b.disabled=true;$('.form-error',f).textContent='';const values=new FormData(f);try{state.session=await api('login',{method:'POST',body:JSON.stringify({username:values.get('username'),password:values.get('password'),remember:values.has('remember')})});route();await load();}catch(err){$('.form-error',f).textContent=err.message;b.disabled=false;}});
}
function route(){const page=location.hash.slice(1)||'home';const valid=[...tabs.map(t=>t[0]),'review','reconcile'];state.page=valid.includes(page)?page:'home';if(state.page==='home')state.account='All accounts';}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;
 if(el.tagName==='A'&&el.getAttribute('href')?.startsWith('#'))state.query='';
 if(el.dataset.resolveSymbol){symbolEditor(Number(el.dataset.resolveSymbol));return;}if(el.dataset.evidence){showEvidence(Number(el.dataset.evidence));return;}if(el.dataset.holding){holdingDetail(el.dataset.holding,el.dataset.account);return;}if(el.dataset.trade){tradeDetail(el.dataset.trade);return;}if(el.dataset.editTarget){targetEditor(el.dataset.editTarget);return;}if(el.dataset.attention){attentionDetail(el.dataset.attention);return;}if(el.dataset.activity){state.activity=el.dataset.activity;state.activityStatus='All statuses';renderContent();return;}
 switch(el.dataset.action){case 'classify':classificationDialog();break;case 'reconcile':location.hash='reconcile';break;case 'run-reconciliation':await runReconciliation();break;case 'export-reconciliation':exportReconciliation();break;case 'symbols':symbolInbox();break;case 'close':closeDetail();break;case 'review':state.query='';location.hash='review';break;case 'install':installDetail();break;case 'budget':budgetEditor();break;case 'refresh':await refreshAccounts();break;case 'reload':await load();break;case 'logout':try{await api('logout',{method:'POST',body:'{}'});state.session=null;state.data=null;state.reconciliation=null;closeDetail();loginPage();}catch(err){toast(err.message);}break;case 'export-holdings':exportRows(filteredHoldings(),['tradingsymbol','account_label','quantity','average_price','last_price'],'capital-holdings.csv');break;case 'export-trades':exportRows(state.data.trades,['trade_id','stock_name','symbol','buy_date','status','my_buy_qty','my_buy_price','target_price','my_sell_date','my_sell_price','my_gain_loss'],'capital-ledger.csv');break;}
});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const box=e.target.getBoundingClientRect();if(e.clientX<box.left)closeDetail();}});
$('#detail').addEventListener('cancel',()=>{lastFocus?.focus?.();});
window.addEventListener('hashchange',()=>{route();closeDetail();render();window.scrollTo({top:0});$('#content h1')?.focus({preventScroll:true});});
window.addEventListener('offline',()=>{closeDetail();state.data=null;state.reconciliation=null;state.error='You’re offline. Reconnect to view your account information.';render();});
window.addEventListener('online',()=>{if(state.session)load();else boot();});
window.addEventListener('pageshow',e=>{if(e.persisted)boot();});
async function boot(){try{state.session=await api('session');route();await load();}catch(e){loginPage(navigator.onLine?'':"You’re offline. Reconnect to sign in.");}}
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
boot();

function symbolInbox(){const rows=state.data.trades.filter(t=>t.status==='NEEDS_REVIEW');openDetail('Confirm stock symbols',`<p>Match each recommendation to its exact company. Confirming a symbol does not place an order.</p>${rows.map(t=>`<div class="lot"><div class="lot-head"><b>${esc(t.stock_name)} · #${t.trade_id}</b></div><p>${esc(t.notes||'The bot needs an exact symbol.')}</p><button class="btn primary" data-resolve-symbol="${t.trade_id}">Check symbol ${icon('arrow')}</button></div>`).join('')||empty('No symbols awaiting confirmation','New unresolved recommendations appear here automatically.')}`);}
function symbolEditor(tid){const t=state.data.trades.find(t=>t.trade_id===tid);if(!t||t.status!=='NEEDS_REVIEW')return;openDetail(`Confirm · ${t.stock_name}`,`<p>Recommendation #${tid} · ${esc(t.category_name)}</p><p class="notebox">A similar-looking ticker can belong to a different company. Compare the company name before confirming.</p><form id="symbol-form"><label class="form-field">Exact NSE trading symbol<input name="symbol" autocomplete="off" autocapitalize="characters" maxlength="40" pattern="[A-Za-z0-9&.\\-]+" required placeholder="For example, VOLTAMP" value="${esc(t.symbol||'')}"></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Check symbol</button></form><div id="symbol-preview"></div>`);
 const form=$('#symbol-form');let preview=null;
 $('input',form).addEventListener('input',()=>{preview=null;$('#symbol-preview').innerHTML='';});
 form.addEventListener('submit',async e=>{e.preventDefault();preview=null;$('#symbol-preview').innerHTML='';const button=$('button',form),symbol=$('input',form).value.trim().toUpperCase();button.disabled=true;$('.form-error',form).textContent='';try{const checked=await api(`trades/${tid}/symbol-preview`,{method:'POST',body:JSON.stringify({symbol})});if($('input',form).value.trim().toUpperCase()!==symbol)return;preview=checked;$('#symbol-preview').innerHTML=`<section class="panel" style="margin-top:22px"><h3>${esc(checked.company_name)}</h3><p>${esc(checked.exchange)} · <b>${esc(checked.symbol)}</b></p><p>${esc(checked.cap_type||'Classification not available')} · advisory price ${money(checked.recommended_price,2)}</p><p class="disclosure">This is the exact equity entry in the broker’s current instrument list. Confirm only if it is the company named in your recommendation.</p><label class="checkbox" style="margin-top:18px"><input id="company-match" type="checkbox">I have checked that this is the same company</label><button class="btn primary" id="confirm-symbol" disabled>Confirm ${esc(checked.symbol)}</button><p class="disclosure">The recommendation returns to the normal buy queue. Interest, score, budget and execution checks still apply.</p></section>`;$('#company-match').addEventListener('change',ev=>$('#confirm-symbol').disabled=!ev.target.checked);$('#confirm-symbol').addEventListener('click',async ev=>{ev.target.disabled=true;try{await api(`trades/${tid}/symbol-confirm`,{method:'POST',body:JSON.stringify({preview_token:preview.preview_token})});closeDetail();toast('Symbol confirmed. Normal scheduled checks still apply.');await load();}catch(err){$('.form-error',form).textContent=err.message;ev.target.disabled=false;}});}catch(err){$('.form-error',form).textContent=err.message;}finally{button.disabled=false;}});
}
function classificationDialog(){openDetail('Find a company',`<form id="classification-form"><label class="form-field">Company name or trading symbol<input name="q" required minlength="2" maxlength="100" placeholder="For example, BGR Energy"></label><button class="btn primary" type="submit">Search classification</button><div class="form-error" role="alert"></div></form><div id="classification-results" style="margin-top:20px"></div>`);$('#classification-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=$('button',f);b.disabled=true;try{const r=await api('classification?q='+encodeURIComponent(new FormData(f).get('q')));$('#classification-results').innerHTML=r.matches.map(m=>`<div class="lot"><h3>${esc(m.company_name)}</h3><p><b>${esc(m.symbol)}</b> · ${esc(m.cap_type)}</p><p>AMFI rank ${number(m.amfi_rank)} · source ${esc(m.source_period)}</p></div>`).join('')||empty('No match','Try the exact exchange symbol or a shorter company name.');}catch(err){$('.form-error',f).textContent=err.message;}finally{b.disabled=false;}});}
function parsed(value,fallback){if(typeof value==='object'&&value!==null)return value;try{return JSON.parse(value||'');}catch{return fallback;}}
async function showEvidence(tid){openDetail('Score evidence & history','<p role="status">Loading the recorded research…</p>');try{const r=await api(`trades/${tid}/evidence`);if(!$('#detail').open)return;$('.detail-body').innerHTML=r.history.map(x=>{const layers=parsed(x.layers_json,{}),reasons=parsed(x.reasons,[]),warnings=parsed(x.warnings,[]);return `<section class="panel"><div class="idea-head"><h3>${finite(x.score)?number(x.score)+'/100':'Not scored'}</h3>${pill(x.model||'Unknown model')}</div><p>${stamp(x.scored_at)} · ${esc(x.verdict)}</p><p>Evidence coverage: ${finite(x.evidence_pct)?number(x.evidence_pct)+'%':'not recorded'}</p>${[...reasons,...warnings].map(v=>`<p class="notebox">${esc(v)}</p>`).join('')}${Object.entries(layers).map(([name,v])=>`<details class="lot"><summary>${esc(name)} · ${number(v.awarded)} / ${number(v.attempted)} points</summary>${(v.checks||[]).map(c=>`<p style="margin-top:10px"><b>${esc(c.name)}</b> · ${esc(c.status)}<br>${esc(c.detail)}</p>`).join('')}</details>`).join('')}</section>`;}).join('')||empty('No score history','This recommendation has not been scored yet.');}catch(err){$('.detail-body').innerHTML=empty('Could not load evidence',err.message);}}
const flagNames={MISSING_GTT_COVERAGE:'Some holdings have no GTT',SYMBOL_SERIES_REVIEW:'Check exchange series',INVENTORY_REVIEW:'Verify inventory',INTRADAY_REVIEW:'Wait for intraday reconciliation',SETTLEMENT_REVIEW:'T+1 shares need settlement review',REMOVE_CANDIDATE_NO_HOLDING:'No holding: review removal',EXCESS_RESERVED_QUANTITY:'Sell quantities exceed holdings',LEDGER_QUANTITY_MISMATCH:'Ledger quantity differs',LINKED_LOT_QUANTITY_MISMATCH:'GTT lot quantity differs',UNCOVERED_SHARES_TARGET_NEEDED:'Some shares have no confirmed target',TRIGGER_BELOW_SNAPSHOT_PRICE_REVIEW_INTENT:'Trigger is below current snapshot price'};
function reconcilePage(){const r=state.reconciliation;return heading('Match your holdings to your triggers.','A fresh, read-only check of both broker accounts and the ledger.','Reconciliation',`<button class="btn primary" data-action="run-reconciliation">${icon('refresh')}Check now</button>`)+`<p class="attention-intro">${icon('shield')}This creates a review plan. It does not add, edit or cancel broker instructions. GTT changes must be made in Kite.</p>`+(!r?empty('Start with a fresh account check','We compare holdings, T+1 shares, intraday positions, pending sells and active GTTs. NSE/BSE display exchanges are not treated as separate holdings.'): `${syncReport(r)}<div class="toolbar"><button class="btn" data-action="export-reconciliation">${icon('download')}Download report</button><a class="btn" href="https://kite.zerodha.com" target="_blank" rel="noopener noreferrer">Open Kite ${icon('external')}</a></div>${Object.entries(r.accounts).filter(([,a])=>a.error).map(([account,a])=>`<div class="load-error">${esc(account)}: ${esc(a.error)}</div>`).join('')}<div class="cards-grid">${r.rows.map(x=>`<section class="idea-card"><div class="idea-head"><h3>${esc(x.symbol)}</h3>${pill(x.account)}</div><p class="subtle-note">${number(x.held)} held · ${number(x.t1)} T+1 · ${number(x.reserved)} in GTTs · ${number(x.uncovered)} uncovered</p><div>${x.flags.map(f=>`<p style="margin:5px 0">${pill(flagNames[f]||f,'amber')}</p>`).join('')||pill('Quantity covered')}</div>${x.target_missing_qty?`<p class="subtle-note">${number(x.target_missing_qty)} uncovered shares have no recorded target.</p>`:''}${x.triggers.map(g=>`<p class="subtle-note">GTT ${esc(g.id)} · ${esc(g.symbol)} · ${number(g.quantity)} shares · trigger ${g.trigger_values.map(v=>money(v,2)).join(' / ')}</p>`).join('')}${x.candidate_lots.map(t=>`<p class="subtle-note"><b>Record #${t.trade_id}:</b> ${number(t.quantity)} shares · recorded target ${money(t.target_price,2)}<br>${esc(t.state==='EXISTING_TARGET_CANDIDATE'?'Existing target to review for an addition':t.state==='WAIT_FOR_SETTLEMENT_REVIEW'?'Review settlement before adding':'Target already crossed or too close; review first')}</p>`).join('')}</section>`).join('')}</div><section class="panel" style="margin-top:22px">${panelHead('Ledger records without holdings','Historical execution evidence is needed before recording an exit.')}${r.ledger_only.map(t=>`<div class="lot"><b>${esc(t.symbol)}</b><p class="subtle-note">${number(t.quantity)} recorded shares · trades ${t.trade_ids.map(id=>'#'+id).join(', ')}</p></div>`).join('')||'<p class="subtle-note">None found in the automated account.</p>'}</section>`);}
function syncReport(r){return `<p class="sync-strip">Checked ${stamp(r.observed_at)}. Candidate quantities and targets require review; nothing has been submitted.</p>`;}
async function runReconciliation(){const buttons=document.querySelectorAll('[data-action="run-reconciliation"]');buttons.forEach(b=>b.disabled=true);toast('Reading holdings, positions and triggers…');try{state.reconciliation=await api('reconciliation',{method:'POST',body:'{}'});renderContent();toast('Reconciliation report ready. No broker orders were changed.');}catch(err){toast(err.message);buttons.forEach(b=>b.disabled=false);}}
function exportReconciliation(){if(!state.reconciliation)return;const u=URL.createObjectURL(new Blob([JSON.stringify(state.reconciliation,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='capital-gtt-reconciliation.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
